return $input.all().map((item, index) => {
  const row = item.json;

  // Find a column by exact name or keyword fallback (fuzzy match)
  const getField = (rowObj, possibleNames, keywords = []) => {
    const keys = Object.keys(rowObj);

    // 1. Exact match
    for (const name of possibleNames) {
      const foundKey = keys.find(k => k.trim().toLowerCase() === name.toLowerCase());
      if (foundKey && rowObj[foundKey] !== undefined && rowObj[foundKey] !== null && rowObj[foundKey].toString().trim() !== '') {
        return rowObj[foundKey];
      }
    }

    // 2. Keyword fallback (e.g. 'desc', 'caus', 'operaz')
    for (const kw of keywords) {
      const foundKey = keys.find(k => k.toLowerCase().includes(kw.toLowerCase()));
      if (foundKey && rowObj[foundKey] !== undefined && rowObj[foundKey] !== null && rowObj[foundKey].toString().trim() !== '') {
        return rowObj[foundKey];
      }
    }

    return '';
  };

  const parseAmount = (val) => {
    if (!val || val.toString().trim() === '' || val === 'undefined') return 0;
    const cleanStr = val.toString().replace(/\./g, '').replace(',', '.');
    return parseFloat(cleanStr) || 0;
  };

  const rawData = getField(row, ['DATA', 'Data', 'Data operazione', 'Data Contabile'], ['data']).toString().trim();

  const rawDesc = getField(
    row, 
    ['DESCRIZIONE', 'Descrizione', 'Causale', 'Descrizione operazione', 'Descrizione estesa', 'Operazione', 'Dettagli', 'Causale ABI'],
    ['desc', 'caus', 'operaz', 'dettagl']
  ).toString().trim();

  const rawDivisa = (getField(row, ['DIVISA', 'Divisa', 'Valuta'], ['divisa', 'valuta']) || 'EUR').toString().trim();

  const dare = parseAmount(getField(row, ['DARE', 'Dare']));
  const avere = parseAmount(getField(row, ['AVERE', 'Avere']));
  const importoSingolo = parseAmount(getField(row, ['IMPORTO', 'Importo']));

  let importoCalcolato = 0;
  if (avere !== 0 || dare !== 0) {
    importoCalcolato = avere > 0 ? avere : -dare;
  } else {
    importoCalcolato = importoSingolo;
  }

  // Prevent SQL syntax errors by escaping apostrophes (e.g. MC DONALD'S -> MC DONALD''S)
  const descClean = rawDesc.replace(/'/g, "''");

  // Adding the index makes each row unique even for identical payments on the same day
  const hashBase = `${rawData}_${rawDivisa}_${rawDesc}_${importoCalcolato}_${index}`;

  return {
    json: {
      data: rawData,
      descrizione: rawDesc,
      descrizione_clean: descClean,
      divisa: rawDivisa,
      importo: importoCalcolato,
      hash_base: hashBase
    }
  };
});

const countMap = {};

return $input.all().map(item => {
  const rawDesc = item.json.descrizione || '';
  const text = rawDesc.toUpperCase();

  // 1. Fixed pre-categorisation rules (generic examples - edit for your own merchants)
  const rules = [
    ['Groceries', ['SUPERMERCATO', 'SUPERMARKET', 'ALIMENTARI']],
    ['Internal Transfer', ['GIROCONTO']],
    ['Utilities', ['UTENZA', 'ENERGIA', 'TELEFONICA']],
    ['Income / Salary', ['EMOLUMENTI', 'STIPENDIO']],
    ['Transport / Car', ['DISTRIBUTORE', 'CARBURANTE']],
    ['Shopping', ['ABBIGLIAMENTO', 'NEGOZIO']],
    ['Cash Withdrawal', ['PRELIEVO', 'ATM', 'BANCOMAT', 'SPORTELLO']]
  ];
  let category = "Other";
  for (const [name, keywords] of rules) {
    if (keywords.some(k => text.includes(k))) { category = name; break; }
  }

  // 2. Mask sensitive data (IBAN, cards, tax codes, dates, times)
  let descMasked = rawDesc
    .replace(/IT\d{2}[A-Z]\d{10}[0-9A-Z]{12}/gi, '[IBAN]')
    .replace(/\b\d{4,6}\*+\d{3,4}\b|\b\d{12,16}\b/g, '[CARD/CODE]')
    .replace(/[A-Z]{6}\d{2}[A-Z]\d{2}[A-Z]\d{3}[A-Z]/gi, '[TAX_CODE]')
    .replace(/\b\d{1,2}[\/\.-]\d{1,2}[\/\.-]\d{2,4}\b|\b\d{4}[\/\.-]\d{1,2}[\/\.-]\d{1,2}\b/g, '[DATE]')
    .replace(/\b([01]?\d|2[0-3])[:.][0-5]\d([:.][0-5]\d)?\b/g, '[TIME]');

  // 3. Strip redundant bank boilerplate from the masked string
  let cleanDesc = descMasked
    .replace(/PAGAMENTO\s+P\.O\.S\./gi, '')
    .replace(/DATA\/ORA:?\s*\[?DATA\]?\s*\[?ORA\]?/gi, '')
    .replace(/DATA\/ORA:?\s*/gi, '')
    .replace(/CARTA\s+N\.\s*\[?CARTA\/CODICE\]?/gi, '')
    .replace(/MAESTRO|VISA|MASTERCARD/gi, '')
    .replace(/\s+/g, ' ')
    .trim();

  const finalDescription = cleanDesc || descMasked || rawDesc;

  // 4. Compute signature and occurrence counter
  const currency = item.json.divisa || 'EUR';
  const signature = `${item.json.data}_${currency}_${finalDescription}_${item.json.importo}`;
  countMap[signature] = (countMap[signature] || 0) + 1;
  const occurrence = countMap[signature];

  // 5. SQL-safe description and unique hash
  const descCleanSQL = finalDescription.replace(/'/g, "''");
  const hashBase = `${item.json.data}_${currency}_${finalDescription}_${item.json.importo}_${occurrence}`;

  return {
    json: {
      ...item.json,
      descrizione: finalDescription,
      descrizione_clean: descCleanSQL,
      categoria_ai: category,
      occurrence: occurrence,
      hash_base: hashBase
    }
  };
});

const categories = [
  'groceries', 'restaurants', 'transport', 'health', 
  'home', 'entertainment', 'services', 'income', 'shopping', 'other'
];

return $input.all().map((item) => {
  // If a category was already assigned by the first node and is not "Other", keep it
  if (item.json.categoria_ai && item.json.categoria_ai !== 'Other') {
    return {
      json: item.json
    };
  }

  // Otherwise read the Ollama response for unrecognised transactions
  const response = (item.json.response || '').toLowerCase().trim();
  let finalCategory = 'Other';

  for (const cat of categories) {
    if (response.includes(cat)) {
      finalCategory = cat.charAt(0).toUpperCase() + cat.slice(1);
      break;
    }
  }

  return {
    json: {
      ...item.json,
      categoria_ai: finalCategory
    }
  };
});
